import json,statistics,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'results'
base=json.loads((OUT/'kinevoa-real-video-test.json').read_text());lateral=json.loads((OUT/'kinevoa-lateral-video-test.json').read_text());base['clips']=[c for c in base['clips'] if c['expected'] != 'Lateral raise'] + lateral['clips']
base['limitations']=['Tiny convenience sample, not a benchmark; no guarantee of subject independence or training-data independence.','Shared native HTTPS request, CA validation, JSON decoding, and display stabilisation executed on Mac; not an optical phone-camera test.','First 12 seconds maximum per clip; 2 Hz sampled frames replayed sequentially without real-time delays.','Classifier weights and thresholds were not changed for this test.','Synthetic anatomical animations were evaluated separately and not mixed with real-person results.']
base['summary']={}
for expected in ['Squat','Push-up','Lateral raise','Unknown']:
 clips=[c for c in base['clips'] if c['expected']==expected]
 base['summary'][expected]={'clips':len(clips),'majority_correct':sum(c['majorityDisplay']==expected for c in clips),'any_correct_display':sum(c['correctDisplay']>0 for c in clips),'correct_frames':sum(c['correctDisplay'] for c in clips),'frames':sum(c['totalFrames'] for c in clips),'wrong_non_unknown_frames':sum(c['wrongDisplay'] for c in clips)}
base['frames']=sum(c['totalFrames'] for c in base['clips']);base['median_request_ms']=statistics.median(f['elapsedMS'] for c in base['clips'] for f in c['frames'])
(OUT/'kinevoa-combined-video-test.json').write_text(json.dumps(base,indent=2))
lines=['# Kinevoa app and web-video test','', 'Native app renamed in header, Home Screen display name, and camera permission text; build 2 installed and launched on Sonia’s connected iPhone. Bundle ID retained so this updates the existing app.','', 'The native camera app’s shared RecognitionRequest, PinnedTrust, RecognitionResponse and RecognitionHistory code was compiled as a Mac replay harness. It sent sampled JPEG frames through the real HTTPS `/predict` service and processed the actual responses. No classifier settings were changed.','', '| Expected | Majority-correct clips | Correct displayed frames |','|---|---:|---:|']
for expected,s in base['summary'].items():lines.append(f'| {expected} | {s["majority_correct"]}/{s["clips"]} | {s["correct_frames"]}/{s["frames"]} |')
lines+=['',f'{base["frames"]} real-person frames; median HTTPS request duration {base["median_request_ms"]:.0f} ms in this run (not camera-to-label latency). Three matching predictions are required for a visible target label, so initial frames normally display Unknown.','', 'Conclusion: the transport/decoding/display path passes, and lateral raise worked on these clips. Squat and push-up recognition are not reliable enough to claim demo readiness. Six non-target clips were rejected correctly.','', 'Sources:','', '- Squat, push-up, shoulder-press and curl: first three lexicographic clips per class in the existing `similar_dataset` source folder of https://huggingface.co/datasets/RickyRiccio/Real_Time_Exercise_Recognition_Dataset .','- Lateral raise: `lateral raise_10.mp4`, `_11.mp4`, `_12.mp4` from https://www.kaggle.com/datasets/hasyimabdillah/workoutfitness-video . Individual-file downloads are ZIPs and were extracted in memory.','', 'An additional nine anatomical-animation videos from https://github.com/luisaraujoc/free-exercise-db-api were tested separately: all six target clips had Unknown as majority output; all three non-target clips were rejected. These are synthetic visuals, not real-person evidence.','', 'Limitations:','']+['- '+x for x in base['limitations']]+['','Full per-frame outcomes: `kinevoa-combined-video-test.json`. Source frames and URLs: `data/real_web_tests/replay.json`. Shared-client harness: `ios/Tests/ReplayWebVideos.swift`. Build log: `kinevoa-build.log`.','', 'Reproduce from workspace root (requires downloaded local public clips and running HTTPS backend):','', '```sh','.venv/bin/python classifier/tools/prepare_real_replay.py','xcrun swiftc -parse-as-library -module-cache-path .cache/swift-module-cache ios/MoveCamera/RecognitionProtocol.swift ios/Tests/ReplayWebVideos.swift -o .cache/replay-web-videos','.cache/replay-web-videos classifier/data/real_web_tests/replay.json https://172.20.10.3:8443/predict .cache/tls/move-demo-ca.cer classifier/results/kinevoa-real-video-test.json','```','']
(OUT/'KINEVOA_TEST_REPORT.md').write_text('\n'.join(lines));print(json.dumps(base['summary'],indent=2))
